public:
    vector<vector<int>> findFarmland(vector<vector<int>>& land) {
        int m = land.size(), n = land[0].size();
        vector<vector<int>> ans;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (land[r][c] == 1) {
                    if ((r == 0 || land[r - 1][c] == 0) && (c == 0 || land[r][c - 1] == 0)) {
                        int r2 = r, c2 = c;
